//#region packages/server/src/wixStore.ts
/**
* The broadcast's storage on Wix Data.
*
* The whole adapter. It is this short because the `Store` interface is
* deliberately narrow — whole-table reads and single-row writes, which is all
* the show has ever done — so nothing in here knows what a bracket is.
*
* ---- Talking to Wix ----
*
* Server to server over the Data v2 REST API, authenticated with an Admin API
* key and a site id. Not the browser SDK: this runs where the key can be kept,
* and the key must never reach a client.
*
* ---- Two things the CMS forced ----
*
* `roster` is a PIPE-DELIMITED STRING, not an array. Wix's CSV import silently
* drops a JSON array column — "5 columns out of 6 will be imported", with no
* mention of which — and a text field is what survives. So the array is joined
* on `|` going in and split coming out, and that conversion lives here rather
* than leaking into the logic.
*
* Collection IDs are `SerialRating` and `BroadcastEpisode`. They are fixed at
* creation and cannot be renamed afterwards, which is why the collections were
* named before anything was imported into them.
*/
const API = "https://www.wixapis.com/wix-data/v2";
/** Wix caps a query page; the pool is walked in these. */
const PAGE = 100;
var WixStore = class {
	key;
	site;
	http;
	constructor(opts) {
		this.key = opts.apiKey;
		this.site = opts.siteId;
		this.http = opts.fetchImpl ?? fetch;
	}
	async call(path, method, body) {
		const res = await this.http(`${API}${path}`, {
			method,
			headers: {
				authorization: this.key,
				"wix-site-id": this.site,
				"content-type": "application/json"
			},
			body: JSON.stringify(body)
		});
		const text = await res.text();
		if (!res.ok) throw new Error(`wix ${method} ${path} -> ${res.status} ${text.slice(0, 300)}`);
		return text ? JSON.parse(text) : {};
	}
	async query(collection, query) {
		return (await this.call("/items/query", "POST", {
			dataCollectionId: collection,
			query
		})).dataItems ?? [];
	}
	async insert(collection, data) {
		await this.call("/items", "POST", {
			dataCollectionId: collection,
			dataItem: { data }
		});
	}
	/**
	* Delete one row.
	*
	* The odd one out: Wix takes the collection as a QUERY parameter here rather
	* than in a body, because a DELETE has none. Sending it the way every other
	* call does answers 400 with no hint as to which of the two is wrong.
	*/
	async remove(collection, id) {
		const q = `?dataCollectionId=${encodeURIComponent(collection)}`;
		const res = await this.http(`${API}/items/${encodeURIComponent(id)}${q}`, {
			method: "DELETE",
			headers: {
				authorization: this.key,
				"wix-site-id": this.site
			}
		});
		if (!res.ok) {
			const text = await res.text();
			throw new Error(`wix DELETE /items/${id} -> ${res.status} ${text.slice(0, 200)}`);
		}
	}
	async update(collection, id, data) {
		await this.call(`/items/${id}`, "PUT", {
			dataCollectionId: collection,
			dataItem: {
				id,
				data
			}
		});
	}
	async listRatings(limit) {
		const out = [];
		for (let offset = 0; offset < limit; offset += PAGE) {
			const items = await this.query("SerialRating", {
				sort: [{
					fieldName: "_createdDate",
					order: "ASC"
				}],
				paging: {
					limit: Math.min(PAGE, limit - offset),
					offset
				}
			});
			for (const it of items) {
				const d = it.data ?? {};
				out.push({
					serial: String(d.serial ?? ""),
					wins: Number(d.wins ?? 0),
					losses: Number(d.losses ?? 0),
					draws: Number(d.draws ?? 0),
					elo: Number(d.elo ?? 1200),
					simVersion: String(d.simVersion ?? "")
				});
			}
			if (items.length < PAGE) break;
		}
		return out;
	}
	/** Every serial already on record, mapped to its row id. */
	async idsBySerial(serials) {
		const found = /* @__PURE__ */ new Map();
		for (let i = 0; i < serials.length; i += PAGE) {
			const batch = serials.slice(i, i + PAGE);
			const items = await this.query("SerialRating", {
				filter: { serial: { $hasSome: batch } },
				paging: { limit: PAGE }
			});
			for (const it of items) {
				const serial = String(it.data?.serial ?? "");
				if (serial && it.id) found.set(serial, it.id);
			}
		}
		return found;
	}
	async addSerials(serials, simVersion) {
		const known = await this.idsBySerial(serials);
		let added = 0;
		for (const serial of serials) {
			if (known.has(serial)) continue;
			await this.insert("SerialRating", {
				serial,
				wins: 0,
				losses: 0,
				draws: 0,
				elo: 1200,
				simVersion
			});
			added++;
		}
		return added;
	}
	async putRatings(rows) {
		const known = await this.idsBySerial(rows.map((r) => r.serial));
		for (const r of rows) {
			const data = {
				serial: r.serial,
				wins: r.wins,
				losses: r.losses,
				draws: r.draws,
				elo: r.elo,
				simVersion: r.simVersion
			};
			const id = known.get(r.serial);
			if (id) await this.update("SerialRating", id, data);
			else await this.insert("SerialRating", data);
		}
	}
	async latestEpisode() {
		return (await this.latestEpisodes(1))[0] ?? null;
	}
	async latestEpisodes(limit) {
		return (await this.query("BroadcastEpisode", {
			sort: [{
				fieldName: "episode",
				order: "DESC"
			}],
			paging: { limit }
		})).map((it) => {
			const d = it.data ?? {};
			return {
				episode: Number(d.episode ?? 0),
				startedAt: Number(d.startedAt ?? 0),
				durationMs: Number(d.durationMs ?? 0),
				roster: String(d.roster ?? "").split("|").filter(Boolean),
				simVersion: String(d.simVersion ?? ""),
				rated: Boolean(d.rated)
			};
		});
	}
	async listPending(limit) {
		const out = [];
		for (let offset = 0; offset < limit; offset += PAGE) {
			const items = await this.query("PendingSerial", {
				sort: [{
					fieldName: "_createdDate",
					order: "ASC"
				}],
				paging: {
					limit: Math.min(PAGE, limit - offset),
					offset
				}
			});
			for (const it of items) {
				const serial = String(it.data?.serial ?? "");
				if (it.id && serial) out.push({
					id: it.id,
					serial
				});
			}
			if (items.length < PAGE) break;
		}
		return out;
	}
	async removePending(ids) {
		for (const id of ids) await this.remove("PendingSerial", id);
	}
	async putEpisode(row) {
		const items = await this.query("BroadcastEpisode", {
			filter: { episode: row.episode },
			paging: { limit: 1 }
		});
		const data = {
			episode: row.episode,
			startedAt: row.startedAt,
			durationMs: row.durationMs,
			roster: row.roster.join("|"),
			simVersion: row.simVersion,
			rated: row.rated
		};
		const id = items[0]?.id;
		if (id) await this.update("BroadcastEpisode", id, data);
		else await this.insert("BroadcastEpisode", data);
	}
};

//#endregion
//#region tools/tick-job.ts
/**
* The scheduled job that keeps the show running.
*
* `tools/live/tick.mjs` is the same body run by hand, against the repo's source
* and the key in `.secrets/`. This one is written to be BUNDLED — one file, no
* repo around it, credentials from the environment — so it can run somewhere
* that is awake when nobody is: see `.github/workflows/tick.yml` in the site
* repo, which runs it on a cron.
*
* Why a cron at all: an episode is a fifteen-minute object, and every viewer
* derives where the show is from its start time. Nothing about that advances
* itself. Without a job calling this, the last episode simply ends and the
* front page says "no tournament on air" for ever — which is exactly the state
* the site was found in, twenty-eight minutes after episode 8 ran out.
*
* It is safe to run far more often than an episode is long. `advance` starts a
* new episode only when the current one has actually finished, and rates a
* finished one only once, so a five-minute cron against a fifteen-minute
* episode is two cheap no-ops and one changeover.
*/
const key = process.env.WIX_ADMIN_KEY?.trim();
const site = process.env.WIX_SITE_ID?.trim();
if (!key) {
	console.error("WIX_ADMIN_KEY is not set. A visitor token cannot write — the");
	console.error("collections refuse it with WDE0027 — so the job cannot advance");
	console.error("the show without it.");
	process.exit(1);
}
if (!site) {
	console.error("WIX_SITE_ID is not set.");
	process.exit(1);
}
const store = new WixStore({
	apiKey: key,
	siteId: site
});
const before = await read(store, Date.now(), "tick");
console.log("before:", JSON.stringify(before.body).slice(0, 200));
const at = Date.now();
const r = await advance(store, at);
if (r.promoted > 0) console.log(`intake: ${r.promoted} new denom(s) into the pool`);
console.log("advance:", r.kind, r.kind === "started" ? r.row.startedAt > at ? `staged episode ${r.row.episode} to begin in ${Math.round((r.row.startedAt - at) / 1e3)}s, field ${r.row.roster.length}, pool ${r.pool}` : `started episode ${r.row.episode} now, field ${r.row.roster.length}, pool ${r.pool}` : r.kind === "live" ? `episode ${r.episode} still on air, next already staged` : `pool ${r.pool}`);
const after = await read(store, Date.now(), "tick");
console.log("after: ", JSON.stringify(after.body).slice(0, 260));
if (r.kind === "idle") {
	console.error(`nothing to run: pool ${r.pool} is too small for a field`);
	process.exit(1);
}

